3	const fs = require('node:fs/promises');
4	const path = require('node:path');
5	const { round6 } = require('./stats');
6	const { parseArgs, EXIT_OK, EXIT_USAGE, EXIT_OUTPUT_ERROR } = require('./collect');
7	const {
8	  loadInput,
9	  buildCompareResult,
10	  decide,
11	  parseNumberOption,
12	  DEFAULT_ALPHA,
13	  DEFAULT_MIN_CHANGE_PERCENT,
14	} = require('./compare');
15	
16	const KNOWN_KEYS = new Set(['manifest', 'output', 'alpha', 'min-change-percent']);
17	
18	function fail(message) {
19	  process.stderr.write(`perf-regress: ${message}\n`);
20	  return EXIT_USAGE;
21	}
22	
23	// Benjamini–Hochberg 校正：m 个 p 值升序后记 p_(1)<=...<=p_(m)，
24	// q_(i) = min(1, min over j>=i (m*p_(j)/j))，再映回原序，保留六位小数。
25	function benjaminiHochberg(pValues) {
26	  const m = pValues.length;
27	  const order = Array.from({ length: m }, (_, i) => i)
28	    .sort((a, b) => pValues[a] - pValues[b]);
29	  const adjusted = new Array(m);
30	  let running = 1;
31	  // 从最大秩向最小秩扫描，累积 min
32	  for (let rank = m; rank >= 1; rank--) {
33	    const index = order[rank - 1];
34	    running = Math.min(running, (m * pValues[index]) / rank);
35	    adjusted[index] = round6(Math.min(1, running));
36	  }
37	  return adjusted;
38	}
39	
40	// 多项归因百分比的中位数：null 按正无穷参与比较；结果为正无穷时写回 null。
41	// 空序列（无具可比性 case 的 ab-suite）同样写 null。
42	function medianPercent(values) {
43	  if (values.length === 0) {
44	    return null;
45	  }
46	  const sorted = values
47	    .map((v) => (v === null ? Infinity : v))
48	    .sort((a, b) => a - b);
49	  const n = sorted.length;
50	  const mid = n >> 1;
51	  const median = n % 2 === 1 ? sorted[mid] : (sorted[mid - 1] + sorted[mid]) / 2;
52	  return median === Infinity ? null : round6(median);
53	}
54	
55	// suite 归因的 dominant_factor，口径与 compare 相同：
56	// central_tendency > tail_latency > variability，取最大正值，无正值为 none。
57	function dominantFactor(central, tail, variability) {
58	  const entries = [
59	    ['central_tendency', central],
60	    ['tail_latency', tail],
61	    ['variability', variability],
62	  ];
63	  let dominant = null;
64	  let best = 0;
65	  for (const [name, percent] of entries) {
66	    const effective = percent === null ? Infinity : percent;
67	    if (effective > 0 && effective > best) {
68	      best = effective;
69	      dominant = name;
70	    }
71	  }
72	  return dominant === null ? 'none' : dominant;
73	}
74	
75	// 读取并校验 manifest：UTF-8 JSON 对象，cases 为非空数组；
76	// 每项 name 非空且唯一，baseline/candidate 非空。
77	// 相对路径按 manifest 所在目录解析。返回 { manifestDir, cases } 或 { error }。
78	async function loadManifest(manifestPath) {
79	  let text;
80	  try {
81	    text = await fs.readFile(manifestPath, 'utf8');
82	  } catch (err) {
83	    return { error: `无法读取 manifest 文件 ${manifestPath}: ${err.message}` };
84	  }
85	  let manifest;
86	  try {
87	    manifest = JSON.parse(text);
88	  } catch {
89	    return { error: `manifest 文件不是合法 JSON: ${manifestPath}` };
90	  }
91	  if (!manifest || typeof manifest !== 'object' || Array.isArray(manifest)) {
92	    return { error: 'manifest 结构无效: 顶层须为对象' };
93	  }
94	  if (!Array.isArray(manifest.cases) || manifest.cases.length === 0) {
95	    return { error: 'manifest cases 必须为非空数组' };
96	  }
97	
98	  const manifestDir = path.dirname(path.resolve(manifestPath));
99	  const cases = [];
100	  const names = new Set();
101	  for (let i = 0; i < manifest.cases.length; i++) {
102	    const item = manifest.cases[i];
103	    if (!item || typeof item !== 'object' || Array.isArray(item)) {
104	      return { error: `manifest cases[${i}] 必须为对象` };
105	    }
106	    if (typeof item.name !== 'string' || item.name === '') {
107	      return { error: `manifest cases[${i}] 的 name 必须为非空字符串` };
108	    }
109	    if (names.has(item.name)) {
110	      return { error: `manifest cases 中 name 重复: ${item.name}` };
111	    }
112	    if (typeof item.baseline !== 'string' || item.baseline === '') {
113	      return { error: `manifest cases[${i}] (${item.name}) 的 baseline 必须为非空字符串` };
114	    }
115	    if (typeof item.candidate !== 'string' || item.candidate === '') {
116	      return { error: `manifest cases[${i}] (${item.name}) 的 candidate 必须为非空字符串` };
117	    }
118	    names.add(item.name);
119	    cases.push({
120	      name: item.name,
121	      baselinePath: path.resolve(manifestDir, item.baseline),
122	      candidatePath: path.resolve(manifestDir, item.candidate),
123	    });
124	  }
125	  return { manifestDir, cases };
126	}
127	
128	async function compareSuite(tokens) {
129	  const { values, error: parseError } = parseArgs(tokens, KNOWN_KEYS);
130	  if (parseError) {
131	    return fail(parseError);
132	  }
133	
134	  const manifestPath = values.manifest;
135	  const output = values.output;
136	  if (manifestPath === undefined || manifestPath === '') {
137	    return fail('--manifest 不能为空');
138	  }
139	  if (output === undefined || output === '') {
140	    return fail('--output 不能为空');
141	  }
142	
143	  const alphaR = parseNumberOption(values, 'alpha', {
144	    defaultValue: DEFAULT_ALPHA,
145	    check: (v) => v > 0 && v < 1,
146	    describe: '满足 0 < alpha < 1',
147	  });
148	  if (alphaR.error) {
149	    return fail(alphaR.error);
150	  }
151	  const minChangeR = parseNumberOption(values, 'min-change-percent', {
152	    defaultValue: DEFAULT_MIN_CHANGE_PERCENT,
