55	async function executeInterleaved(baselineCommand, candidateCommand, runs, warmup, timeoutMs) {
56	  const sides = {
57	    baseline: { command: baselineCommand, samples: [], errors: [] },
58	    candidate: { command: candidateCommand, samples: [], errors: [] },
59	  };
60	  const order = ['baseline', 'candidate'];
61	
62	  const runSide = async (sideName, stage, index) => {
63	    const side = sides[sideName];
64	    let result;
65	    try {
66	      result = await runOnce(side.command, timeoutMs);
67	    } catch {
68	      reportStartupFailure(sideName, stage, index, null);
69	      return false;
70	    }
71	    if (result.reason === 'timeout') {
72	      side.errors.push({ stage, index, reason: 'timeout', exit_code: null });
73	      return true;
74	    }
75	    if (isStartupExitCode(result.exitCode)) {
76	      reportStartupFailure(sideName, stage, index, result.exitCode);
77	      return false;
78	    }
79	    if (result.exitCode !== 0) {
80	      side.errors.push({ stage, index, reason: 'nonzero_exit', exit_code: result.exitCode });
81	      return true;
82	    }
83	    if (stage === 'measure') {
84	      side.samples.push({
85	        index,
