114	    command,
115	    runs,
116	    warmup,
117	    timeout_ms: timeoutMs,
118	    unit: 'ns',
119	    samples: side.samples,
120	    summary: side.samples.length === 0
121	      ? emptySummary()
122	      : computeSummary(side.samples.map((s) => s.duration_ns)),
123	    errors: side.errors,
124	  };
125	}
