133	  const baselineCommand = values['baseline-command'];
134	  const candidateCommand = values['candidate-command'];
135	  const output = values.output;
136	  if (baselineCommand === undefined || baselineCommand === '') {
137	    return fail('--baseline-command 不能为空');
138	  }
139	  if (candidateCommand === undefined || candidateCommand === '') {
140	    return fail('--candidate-command 不能为空');
141	  }
142	  if (output === undefined || output === '') {
143	    return fail('--output 不能为空');
144	  }
145	
146	  const runsR = parsePositiveIntOption(values, 'runs', { min: 2, required: true });
147	  if (runsR.error) {
148	    return fail(runsR.error);
149	  }
150	  const warmupR = parsePositiveIntOption(values, 'warmup', { min: 0, required: false });
151	  if (warmupR.error) {
152	    return fail(warmupR.error);
153	  }
154	  const timeoutR = parsePositiveIntOption(values, 'timeout-ms', { min: 1, required: true });
155	  if (timeoutR.error) {
156	    return fail(timeoutR.error);
157	  }
158	  const alphaR = parseNumberOption(values, 'alpha', {
159	    defaultValue: DEFAULT_ALPHA,
160	    check: (v) => v > 0 && v < 1,
161	    describe: '满足 0 < alpha < 1',
162	  });
163	  if (alphaR.error) {
164	    return fail(alphaR.error);
165	  }
166	  const minChangeR = parseNumberOption(values, 'min-change-percent', {
167	    defaultValue: DEFAULT_MIN_CHANGE_PERCENT,
168	    check: (v) => v >= 0,
169	    describe: '为不小于 0 的数',
170	  });
171	  if (minChangeR.error) {
172	    return fail(minChangeR.error);
173	  }
174	
175	  const runs = runsR.value;
176	  const warmup = warmupR.value === undefined ? 0 : warmupR.value;
177	  const timeoutMs = timeoutR.value;
178	  const alpha = alphaR.value;
179	  const minChangePercent = minChangeR.value;
180	
181	  const { baseline, candidate, fatal } = await executeInterleaved(
182	    baselineCommand, candidateCommand, runs, warmup, timeoutMs);
183	  // 进程无法启动属致命错误：stderr 已报告，不创建或改写 output。
