test('--key=value 写法与可选参数 --alpha/--min-change-percent', () => {
  const out = withTempFile('eq.json');
  const r = runCli(['--baseline-command=true', '--candidate-command=true',
    '--runs=2', '--warmup=0', '--timeout-ms=5000', `--output=${out}`,
