7	function round6(value) {
8	  return Math.round(value * 1e6) / 1e6;
9	}
10	
11	function meanOf(values) {
12	  let sum = 0;
13	  for (const v of values) sum += v;
14	  return sum / values.length;
15	}
16	
17	function medianOfSorted(sorted) {
18	  const n = sorted.length;
19	  const mid = n >> 1;
20	  if (n % 2 === 1) return sorted[mid];
21	  // 偶数样本取中间两值平均（可能为 x.5，无需 round6 也会被统一处理）
22	  return (sorted[mid - 1] + sorted[mid]) / 2;
23	}
24	
25	function p95OfSorted(sorted) {
26	  const n = sorted.length;
27	  // 排序后第 ceil(0.95 * count) 项（1-based -> 转 0-based）
28	  const rank = Math.ceil(0.95 * n);
29	  return sorted[rank - 1];
30	}
