32	function stddevPopulation(values, avg) {
33	  let acc = 0;
34	  for (const v of values) {
35	    const d = v - avg;
36	    acc += d * d;
37	  }
38	  return Math.sqrt(acc / values.length);
39	}
40	
41	function computeSummary(durations) {
42	  const sorted = durations.slice().sort((a, b) => a - b);
43	  const count = sorted.length;
44	  const min = sorted[0];
45	  const max = sorted[count - 1];
46	  const mean = meanOf(sorted);
47	  const median = medianOfSorted(sorted);
48	  const p95 = p95OfSorted(sorted);
49	  const stddev = stddevPopulation(sorted, mean);
50	  return {
51	    count,
52	    min,
53	    max,
54	    mean: round6(mean),
55	    median: round6(median),
56	    p95,
57	    stddev: round6(stddev),
58	  };
59	}
60	
61	// ---- Welch 双侧 t 检验 ----
62	// 无第三方依赖，t 分布 CDF 经正则化不完全 beta 函数求得：
63	// 双侧 p = I_{df/(df+t^2)}(df/2, 1/2)。
64	
65	// Lanczos 近似系数（g = 7, n = 9）
66	const LANCZOS = [
67	  0.99999999999980993,
68	  676.5203681218851,
69	  -1259.1392167224028,
70	  771.32342877765313,
71	  -176.61502916214059,
72	  12.507343278686905,
73	  -0.13857109526572012,
74	  9.9843695780195716e-6,
75	  1.5056327351493116e-7,
76	];
77	
78	function logGamma(z) {
79	  if (z < 0.5) {
80	    // 反射公式
81	    return Math.log(Math.PI / Math.sin(Math.PI * z)) - logGamma(1 - z);
82	  }
83	  const w = z - 1;
84	  let x = LANCZOS[0];
85	  for (let i = 1; i < LANCZOS.length; i++) {
86	    x += LANCZOS[i] / (w + i);
87	  }
88	  const t = w + 7.5;
89	  return 0.5 * Math.log(2 * Math.PI) + (w + 0.5) * Math.log(t) - t + Math.log(x);
90	}
91	
92	// Lentz 连分式求值（Numerical Recipes betacf）
93	function betaContinuedFraction(a, b, x) {
94	  const MAX_ITER = 200;
95	  const EPS = 3e-14;
96	  const FPMIN = 1e-300;
97	  const qab = a + b;
98	  const qap = a + 1;
99	  const qam = a - 1;
100	  let c = 1;
101	  let d = 1 - (qab * x) / qap;
102	  if (Math.abs(d) < FPMIN) d = FPMIN;
103	  d = 1 / d;
104	  let h = d;
105	  for (let m = 1; m <= MAX_ITER; m++) {
106	    const m2 = 2 * m;
107	    let aa = (m * (b - m) * x) / ((qam + m2) * (a + m2));
108	    d = 1 + aa * d;
109	    if (Math.abs(d) < FPMIN) d = FPMIN;
110	    c = 1 + aa / c;
111	    if (Math.abs(c) < FPMIN) c = FPMIN;
112	    d = 1 / d;
113	    h *= d * c;
114	    aa = (-(a + m) * (qab + m) * x) / ((a + m2) * (qap + m2));
115	    d = 1 + aa * d;
116	    if (Math.abs(d) < FPMIN) d = FPMIN;
117	    c = 1 + aa / c;
118	    if (Math.abs(c) < FPMIN) c = FPMIN;
119	    d = 1 / d;
120	    const del = d * c;
121	    h *= del;
122	    if (Math.abs(del - 1) < EPS) break;
123	  }
124	  return h;
125	}
126	
127	// 正则化不完全 beta 函数 I_x(a, b)
128	function regularizedIncompleteBeta(x, a, b) {
129	  if (x <= 0) return 0;
130	  if (x >= 1) return 1;
131	  const lnFront =
132	    a * Math.log(x) + b * Math.log(1 - x) +
133	    logGamma(a + b) - logGamma(a) - logGamma(b);
134	  const front = Math.exp(lnFront);
135	  if (x < (a + 1) / (a + b + 2)) {
136	    return (front * betaContinuedFraction(a, b, x)) / a;
137	  }
138	  return 1 - (front * betaContinuedFraction(b, a, 1 - x)) / b;
139	}
140	
141	// 样本方差（无偏，除以 n-1）；调用方保证 values.length >= 2
142	function sampleVariance(values, avg) {
143	  let acc = 0;
144	  for (const v of values) {
145	    const d = v - avg;
146	    acc += d * d;
147	  }
148	  return acc / (values.length - 1);
149	}
