test('既有入口不受影响（ab-paired 冒烟）', () => {
  const dir = tempDir();
  const out = path.join(dir, 'ab-paired.json');
  const r = spawnSync(process.execPath,
    [BIN, 'ab-paired', '--baseline-command', 'true', '--candidate-command', 'true',
      '--runs', '2', '--timeout-ms', '5000', '--output', out],
    { encoding: 'utf8' });
